// 承認の業務ルール(2・3・6)を Service でチェックする流れ
// ここを変えてみよう:amount を 99_999 / 100_000 に、actor を taro / bucho / hanako に
class BusinessRuleException extends RuntimeException {
    BusinessRuleException(String message) { super(message); }
}
enum Role { APPLICANT, APPROVER, ADMIN }
record Employee(long id, String name, Role role) {}
record History(String action, String actor) {}

class Request {
    final Employee applicant;
    final Integer amount;
    String status = "SUBMITTED";
    Request(Employee applicant, Integer amount) {
        this.applicant = applicant;
        this.amount = amount;
    }
    void approve() {                       // 状態のルールはエンティティが守る
        if (!status.equals("SUBMITTED")) {
            throw new BusinessRuleException(status + " の申請は承認できません");
        }
        status = "APPROVED";
    }
}

List<History> histories = new ArrayList<>();

void approve(Request r, Employee actor) {  // 「誰が」のルールは Service が守る
    if (actor.role() == Role.APPLICANT) {
        throw new BusinessRuleException("承認者・管理者しか操作できません");
    }
    if (r.applicant.id() == actor.id()) {
        throw new BusinessRuleException("自分の申請は承認できません");
    }
    if (r.amount != null && r.amount >= 100_000 && actor.role() != Role.ADMIN) {
        throw new BusinessRuleException("100,000円以上の申請は管理者しか承認できません");
    }
    r.approve();
    histories.add(new History("APPROVE", actor.name()));   // 成功した後に履歴
}

Employee hanako = new Employee(1, "花子", Role.APPLICANT);
Employee taro = new Employee(2, "太郎", Role.APPROVER);
Employee bucho = new Employee(3, "部長", Role.ADMIN);

Integer amount = 100_000;
Employee actor = taro;

Request r = new Request(hanako, amount);
try {
    approve(r, actor);
    System.out.println(actor.name() + " が承認しました → " + r.status);
} catch (BusinessRuleException e) {
    System.out.println("ルール違反: " + e.getMessage() + "(状態は " + r.status + " のまま)");
}
try {
    approve(r, bucho);                     // 2回目(1回目が成功していれば状態のルールで失敗)
    System.out.println("部長が承認しました → " + r.status);
} catch (BusinessRuleException e) {
    System.out.println("ルール違反: " + e.getMessage());
}
System.out.println("履歴 " + histories.size() + " 件: " + histories);

// 楽観ロック(@Version)の仕組みをメモリ上で再現する
// ここを変えてみよう:checkVersion を false にすると、二重承認が通ってしまう
boolean checkVersion = true;

class Row {                 // DB の1行のつもり
    String status = "SUBMITTED";
    long version = 0;
}
record Snapshot(String status, long version) {}   // 各トランザクションが読んだ値

Row row = new Row();
List<String> histories = new ArrayList<>();

// UPDATE approval_request SET status=?, version=version+1
//  WHERE id=? AND version=?  ← 読んだときの version で絞り込む
void approveAndCommit(String who, Snapshot read) {
    if (!read.status().equals("SUBMITTED")) {
        System.out.println(who + ": 承認済なので承認できません");
        return;
    }
    if (checkVersion && row.version != read.version()) {
        System.out.println(who + ": 更新 0 件 → 楽観ロック失敗(ロールバック。履歴も残らない)");
        return;
    }
    row.status = "APPROVED";
    row.version++;
    histories.add("APPROVE by " + who);
    System.out.println(who + ": 承認してコミット(version=" + row.version + ")");
}

// 太郎と部長が「ほぼ同時に」同じ申請を読み込む
Snapshot taroRead = new Snapshot(row.status, row.version);
Snapshot buchoRead = new Snapshot(row.status, row.version);

approveAndCommit("太郎", taroRead);
approveAndCommit("部長", buchoRead);
System.out.println("最終状態: " + row.status + " / 履歴: " + histories);

